#!/usr/bin/env python3

"""Generate the canonical-normalization lookup tables in bounded shards."""

from __future__ import annotations

import unicodedata
from pathlib import Path


UNICODE_VERSION = "16.0.0"
SHARD_SIZE = 450
ROOT = Path(__file__).resolve().parent


def go_header(description: str) -> list[str]:
    return [
        "// Code generated by generate_unicode_tables.py; DO NOT EDIT.",
        "",
        "package template",
        "",
        f"// {description}",
    ]


def canonical_decompositions() -> list[tuple[int, int, int]]:
    entries: list[tuple[int, int, int]] = []
    for value in range(0x110000):
        # Hangul syllables are decomposed algorithmically by unicode_normalize.go.
        if 0xAC00 <= value <= 0xD7A3:
            continue
        raw = unicodedata.decomposition(chr(value))
        if not raw or raw.startswith("<"):
            continue
        parts = [int(part, 16) for part in raw.split()]
        if len(parts) > 2:
            raise RuntimeError(f"unexpected canonical decomposition for U+{value:04X}: {raw}")
        entries.append((value, parts[0], parts[1] if len(parts) == 2 else 0))
    return entries


def combining_classes() -> list[tuple[int, int]]:
    entries: list[tuple[int, int]] = []
    for value in range(0x110000):
        combining_class = unicodedata.combining(chr(value))
        if combining_class:
            entries.append((value, combining_class))
    return entries


def remove_stale_shards(pattern: str) -> None:
    for path in ROOT.glob(pattern):
        path.unlink()


def write_decomposition_tables(entries: list[tuple[int, int, int]]) -> None:
    remove_stale_shards("unicode_normalize_table_[0-9][0-9].go")
    names: list[str] = []
    for index, start in enumerate(range(0, len(entries), SHARD_SIZE)):
        name = f"canonicalDecompositionTable{index:02d}"
        names.append(name)
        lines = go_header(f"Unicode {UNICODE_VERSION} canonical decompositions, shard {index + 1}.")
        lines.append(f"var {name} = [...]canonicalDecompositionEntry{{")
        for source, first, second in entries[start : start + SHARD_SIZE]:
            lines.append(f"\t{{0x{source:04X}, 0x{first:04X}, 0x{second:04X}}},")
        lines.extend(["}", ""])
        (ROOT / f"unicode_normalize_table_{index:02d}.go").write_text("\n".join(lines))

    lines = go_header(f"Unicode {UNICODE_VERSION} canonical decomposition table index.")
    lines.extend(
        [
            "type canonicalDecompositionEntry struct {",
            "\tfrom rune",
            "\tto1  rune",
            "\tto2  rune",
            "}",
            "",
            "var canonicalDecompositionTable = joinCanonicalDecompositionTables(",
        ]
    )
    lines.extend(f"\t{name}[:]," for name in names)
    lines.extend(
        [
            ")",
            "",
            "func joinCanonicalDecompositionTables(tables ...[]canonicalDecompositionEntry) []canonicalDecompositionEntry {",
            "\tsize := 0",
            "\tfor _, table := range tables {",
            "\t\tsize += len(table)",
            "\t}",
            "\tjoined := make([]canonicalDecompositionEntry, 0, size)",
            "\tfor _, table := range tables {",
            "\t\tjoined = append(joined, table...)",
            "\t}",
            "\treturn joined",
            "}",
            "",
        ]
    )
    (ROOT / "unicode_normalize_tables.go").write_text("\n".join(lines))


def write_combining_class_tables(entries: list[tuple[int, int]]) -> None:
    remove_stale_shards("unicode_combining_class_table_[0-9][0-9].go")
    names: list[str] = []
    for index, start in enumerate(range(0, len(entries), SHARD_SIZE)):
        name = f"canonicalCombiningClassTable{index:02d}"
        names.append(name)
        lines = go_header(f"Unicode {UNICODE_VERSION} canonical combining classes, shard {index + 1}.")
        lines.append(f"var {name} = [...]canonicalCombiningClassEntry{{")
        for value, combining_class in entries[start : start + SHARD_SIZE]:
            lines.append(f"\t{{0x{value:04X}, {combining_class}}},")
        lines.extend(["}", ""])
        (ROOT / f"unicode_combining_class_table_{index:02d}.go").write_text("\n".join(lines))

    lines = go_header(f"Unicode {UNICODE_VERSION} canonical combining-class table index.")
    lines.extend(
        [
            "type canonicalCombiningClassEntry struct {",
            "\tr     rune",
            "\tclass uint8",
            "}",
            "",
            "var canonicalCombiningClassTable = joinCanonicalCombiningClassTables(",
        ]
    )
    lines.extend(f"\t{name}[:]," for name in names)
    lines.extend(
        [
            ")",
            "",
            "func joinCanonicalCombiningClassTables(tables ...[]canonicalCombiningClassEntry) []canonicalCombiningClassEntry {",
            "\tsize := 0",
            "\tfor _, table := range tables {",
            "\t\tsize += len(table)",
            "\t}",
            "\tjoined := make([]canonicalCombiningClassEntry, 0, size)",
            "\tfor _, table := range tables {",
            "\t\tjoined = append(joined, table...)",
            "\t}",
            "\treturn joined",
            "}",
            "",
        ]
    )
    (ROOT / "unicode_combining_class_table.go").write_text("\n".join(lines))


def main() -> None:
    if unicodedata.unidata_version != UNICODE_VERSION:
        raise SystemExit(
            f"requires Python unicodedata {UNICODE_VERSION}; found {unicodedata.unidata_version}"
        )
    write_decomposition_tables(canonical_decompositions())
    write_combining_class_tables(combining_classes())


if __name__ == "__main__":
    main()
